import{_ as l,C as d,o as s,c as e,j as i,E as r,a as n,a3 as o}from"./chunks/framework.C6R8kWFE.js";const q=JSON.parse(`{"title":"4-hafta (Mentor)","description":"","frontmatter":{"title":"4-hafta (Mentor)","layout":"doc","sidebar":false,"aside":false,"outline":false,"kind":"mentor_hafta","hafta":{"sinf":{"name":"9-sinf (UX/UI)","link":"/mentor/9-sinf/"},"n":4,"bob":"I-bob · UX/UI dizayn nazariyasi va asoslari","lessons":[{"g":10,"title":"Shrift (tipografiya) va uning UX dizaynga ta'siri","lead":"Chiroyli rasm va tugmalar bo'lsa-yu, matnni o'qib bo'lmasa, ilovadan kim foydalanadi? Ushbu darsda interfeysning \\"ovoz ohangi\\" hisoblangan tipografiya, shrift turlari va ularni Figma'da sozlashni o'rganamiz.","link":"/mentor/9-sinf/hafta-04/dars-1","slide":"/slaydlar/9-sinf/hafta-04/dars-1.html","test":"/slaydlar/9-sinf/hafta-04/dars-1-test.html"},{"g":11,"title":"UI elementlarida rang nazariyasi","lead":"Nega ayrim ilovalar ko'zni quvontiradi, boshqalari esa 5 soniyada charchatadi? Ushbu darsda ranglar g'ildiragi, 4 xil rang palitrasi, 60-30-10 qoidasi va WCAG kontrast talablarini o'rganamiz.","link":"/mentor/9-sinf/hafta-04/dars-2","slide":"/slaydlar/9-sinf/hafta-04/dars-2.html","test":"/slaydlar/9-sinf/hafta-04/dars-2-test.html"},{"g":12,"title":"UI kompozitsiyasi va vizual ierarxiya asoslari","lead":"Shriftlar va ranglar chiroyli tanlangan, lekin interfeysda nima qayerdaligi tushunarsizmi? Ushbu darsda kompozitsiyaning 4 oltin tamoyili, vizual ierarxiya va bo'sh joy (White space) qudratini o'rganamiz.","link":"/mentor/9-sinf/hafta-04/dars-3","slide":"/slaydlar/9-sinf/hafta-04/dars-3.html","test":"/slaydlar/9-sinf/hafta-04/dars-3-test.html"}],"test":"/slaydlar/9-sinf/hafta-04/hafta-test.html"}},"headers":[],"relativePath":"mentor/9-sinf/hafta-04/index.md","filePath":"mentor/9-sinf/hafta-04/index.md"}`),h={name:"mentor/9-sinf/hafta-04/index.md"},g={class:"blk"},u={id:"uyga-vazifa-va-mentor-tavsiyalari",tabindex:"-1"},m={class:"blk"},f={id:"baholash-mezoni",tabindex:"-1"};function y(_,a,c,v,b,k){const t=d("Icon");return s(),e("div",null,[i("div",g,[i("h2",u,[r(t,{name:"house"}),a[0]||(a[0]=n(" Uyga vazifa va mentor tavsiyalari ",-1)),a[1]||(a[1]=i("a",{class:"header-anchor",href:"#uyga-vazifa-va-mentor-tavsiyalari","aria-label":'Permalink to "<Icon name="house" /> Uyga vazifa va mentor tavsiyalari"'},"​",-1))]),a[2]||(a[2]=o('<p>Har bir vazifa 20–30 daqiqa. Natijalarni Figma dasturidagi alohida faylda saqlang. Topshirish: keyingi dars boshida mentorga Figma havolasini ko&#39;rsating.</p><h2 id="_10-dars-uchun-shrift-va-tipografiya" tabindex="-1">10-dars uchun (Shrift va tipografiya) <a class="header-anchor" href="#_10-dars-uchun-shrift-va-tipografiya" aria-label="Permalink to &quot;10-dars uchun (Shrift va tipografiya)&quot;">​</a></h2><p><strong>1-topshiriq: «Tipografik ierarxiya va shrift juftligi»</strong></p><ol><li>Figma&#39;da <code>Mobile (375x812)</code> o&#39;lchamli Frame oching.</li><li>Google Fonts&#39;dan ikkita shrift juftligini tanlang (masalan: Sarlavhalar uchun <em>Poppins</em>, asosiy matn uchun <em>Inter</em>).</li><li>Yangiliklar kartasi dizaynini yarating: <ul><li>Kategoriya tegi: <code>10px BOLD</code>, bosh harflarda;</li><li>Asosiy sarlavha: <code>20px SemiBold</code>, Line Height: <code>130%</code>;</li><li>Qisqa tavsif: <code>14px Regular</code>, Line Height: <code>150%</code>;</li><li>Sana va muallif: <code>12px Muted (och kulrang)</code>.</li></ul></li></ol><p><strong>Kutiladigan natija:</strong> o&#39;qilishi oson, tipografik ierarxiyasi to&#39;g&#39;ri qurilgan yangilik kartasi.</p><hr><h2 id="_11-dars-uchun-ui-elementlarida-rang-nazariyasi" tabindex="-1">11-dars uchun (UI elementlarida rang nazariyasi) <a class="header-anchor" href="#_11-dars-uchun-ui-elementlarida-rang-nazariyasi" aria-label="Permalink to &quot;11-dars uchun (UI elementlarida rang nazariyasi)&quot;">​</a></h2><p><strong>2-topshiriq: «60-30-10 rang palitrasi va kontrast»</strong></p><ol><li>Figma&#39;da o&#39;zingiz tanlagan brend yo&#39;nalishi (masalan: ekologik mahsulotlar yoki musiqa ilovasi) uchun 3 ta rang tanlang (60% fon, 30% karta foni, 10% yorqin brend CTA tugmasi).</li><li>Shu ranglar asosida bitta «Mahsulot kartasi» (Product Card) chizing: Rasm, Mahsulot nomi, Narxi, Chegirma belgisi va «Sotib olish» tugmasi.</li><li>WebAIM Contrast Checker orqali tugma foni va matni orasidagi kontrast kamida <code>4.5:1</code> ekanligini tekshiring.</li></ol><p><strong>Kutiladigan natija:</strong> 60-30-10 qoidasiga mos, WCAG kontrast talablariga javob beruvchi chiroyli karta.</p><hr><h2 id="_12-dars-uchun-ui-kompozitsiyasi-va-vizual-ierarxiya" tabindex="-1">12-dars uchun (UI kompozitsiyasi va vizual ierarxiya) <a class="header-anchor" href="#_12-dars-uchun-ui-kompozitsiyasi-va-vizual-ierarxiya" aria-label="Permalink to &quot;12-dars uchun (UI kompozitsiyasi va vizual ierarxiya)&quot;">​</a></h2><p><strong>3-topshiriq: «E-kutubxona to&#39;liq bosh ekrani»</strong></p><ol><li>Hafta davomida o&#39;rganilgan barcha bilimlarni (Tipografiya, Rang, Kompozitsiya) birlashtiring.</li><li>«E-kutubxona» mobil ilovasi bosh sahifasini 8-point grid qoidasi bo&#39;yicha chizing: <ul><li>Yuqori panel: Profil avatari, qidiruv satri;</li><li>Kompozitsion markaz: Katta «Hafta tavsiyasi» banneri va yorqin «O&#39;qishni boshlash» tugmasi;</li><li>Ritm: Gorizontal aylanuvchi «Ommabop kitoblar» kartalari qatori (bir xil 16px oraliq bilan);</li><li>Pastki navigatsiya: 4 ta asosiy bo&#39;lim ikonkalari.</li></ul></li></ol><p><strong>Kutiladigan natija:</strong> professional, muvozanatli va I-bob talablariga to&#39;liq javob beruvchi mobil bosh sahifa UI maketi.</p><hr><h2 id="mentor-uchun" tabindex="-1">Mentor uchun <a class="header-anchor" href="#mentor-uchun" aria-label="Permalink to &quot;Mentor uchun&quot;">​</a></h2><p>Dars boshida o&#39;quvchilarning shrift tanlovlarini tahlil qiling: dekorativ shriftlar asosiy matnda ishlatilmaganiga ishonch hosil qiling. 11-darsda tugma kontrasti tekshirilganini ko&#39;ring (sariq fonga oq matn kabi xatolarni tuzating). 12-darsda 8-point grid masofalari (<code>16px</code>, <code>24px</code>) qat&#39;iy saqlanganini tekshiring.</p>',18))]),i("div",m,[i("h2",f,[r(t,{name:"list-checks"}),a[3]||(a[3]=n(" Baholash mezoni ",-1)),a[4]||(a[4]=i("a",{class:"header-anchor",href:"#baholash-mezoni","aria-label":'Permalink to "<Icon name="list-checks" /> Baholash mezoni"'},"​",-1))]),a[5]||(a[5]=o('<p>Guruhdagi har bir o&#39;quvchi uchun haftalik natijalar qaydnomasi.</p><p><strong>Guruh:</strong> 9-sinf (UX/UI dizayn va Advanced Front-end) <strong>Hafta:</strong> 4-hafta <strong>Mentor:</strong> ____________________</p><h2 id="shkala-va-mezonlar" tabindex="-1">Shkala va mezonlar <a class="header-anchor" href="#shkala-va-mezonlar" aria-label="Permalink to &quot;Shkala va mezonlar&quot;">​</a></h2><p>100 ballik shkala: <strong>90–100 — 5 (a&#39;lo)</strong>, <strong>71–89 — 4 (yaxshi)</strong>, <strong>60–70 — 3 (qoniqarli)</strong>, <strong>0–59 — 2 (qoniqarsiz)</strong>.</p><table tabindex="0"><thead><tr><th>Mezon</th><th>Max</th></tr></thead><tbody><tr><td>Nazariy tushuncha (tezkor nazorat, og&#39;zaki)</td><td>30</td></tr><tr><td>Amaliy topshiriq (Figma&#39;dagi dizayn sifati)</td><td>30</td></tr><tr><td>Dizayn intizomi (8-point grid, WCAG kontrasti, tipografik ierarxiya)</td><td>20</td></tr><tr><td>Uyga vazifa (o&#39;z vaqtida va to&#39;liq bajarilishi)</td><td>20</td></tr><tr><td><strong>Jami</strong></td><td><strong>100</strong></td></tr></tbody></table><hr><h2 id="o-quvchilar-natijalari-jadvali" tabindex="-1">O&#39;quvchilar natijalari jadvali <a class="header-anchor" href="#o-quvchilar-natijalari-jadvali" aria-label="Permalink to &quot;O&#39;quvchilar natijalari jadvali&quot;">​</a></h2><table tabindex="0"><thead><tr><th>№</th><th>O&#39;quvchi F.I.Sh.</th><th>10-dars (shrift) /100</th><th>11-dars (rang) /100</th><th>12-dars (kompozitsiya) /100</th><th>O&#39;rtacha ball</th><th>Hafta bahosi</th></tr></thead><tbody><tr><td>1</td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>2</td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>3</td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>4</td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>5</td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>6</td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>7</td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>8</td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>9</td><td></td><td></td><td></td><td></td><td></td><td></td></tr><tr><td>10</td><td></td><td></td><td></td><td></td><td></td><td></td></tr></tbody></table><hr><h2 id="darslar-bo-yicha-e-tibor-qaratiladigan-nuqtalar" tabindex="-1">Darslar bo&#39;yicha e&#39;tibor qaratiladigan nuqtalar <a class="header-anchor" href="#darslar-bo-yicha-e-tibor-qaratiladigan-nuqtalar" aria-label="Permalink to &quot;Darslar bo&#39;yicha e&#39;tibor qaratiladigan nuqtalar&quot;">​</a></h2><h3 id="_10-dars-shrift-tipografiya-va-uning-ux-dizaynga-ta-siri" tabindex="-1">10-dars. Shrift (tipografiya) va uning UX dizaynga ta&#39;siri <a class="header-anchor" href="#_10-dars-shrift-tipografiya-va-uning-ux-dizaynga-ta-siri" aria-label="Permalink to &quot;10-dars. Shrift (tipografiya) va uning UX dizaynga ta&#39;siri&quot;">​</a></h3><ul><li>Typeface va Font farqini to&#39;g&#39;ri tushunishi;</li><li>Serif va Sans Serif shriftlarini to&#39;g&#39;ri vaziyatda tanlay olishi;</li><li>Figma Typography panelida o&#39;lcham va qalinliklarni ierarxik sozlashi.</li></ul><h3 id="_11-dars-ui-elementlarida-rang-nazariyasi" tabindex="-1">11-dars. UI elementlarida rang nazariyasi <a class="header-anchor" href="#_11-dars-ui-elementlarida-rang-nazariyasi" aria-label="Permalink to &quot;11-dars. UI elementlarida rang nazariyasi&quot;">​</a></h3><ul><li>4 xil palitrani (monoxromatik, analog, komplementar, triadik) farqlashi;</li><li>60-30-10 qoidasini amalda to&#39;g&#39;ri qo&#39;llashi;</li><li>WCAG bo&#39;yicha 4.5:1 minimal kontrast talabiga rioya qilishi.</li></ul><h3 id="_12-dars-ui-kompozitsiyasi-va-vizual-ierarxiya-asoslari" tabindex="-1">12-dars. UI kompozitsiyasi va vizual ierarxiya asoslari <a class="header-anchor" href="#_12-dars-ui-kompozitsiyasi-va-vizual-ierarxiya-asoslari" aria-label="Permalink to &quot;12-dars. UI kompozitsiyasi va vizual ierarxiya asoslari&quot;">​</a></h3><ul><li>Simmetrik va asimmetrik balansni tushunishi;</li><li>Kompozitsion markaz (Focal Point) orqali asosiy CTA tugmaga urg&#39;u berishi;</li><li>8-point grid tizimi va White Space tamoyillarini to&#39;liq qo&#39;llashi.</li></ul><hr><p><strong>Mentor xulosasi va tavsiyalari:</strong> __________________________________________________</p>',18))])])}const z=l(h,[["render",y]]);export{q as __pageData,z as default};
